`timescale 1ns / 1ps
// Repro: a start pulse while a frame is in flight must be ignored
// (uart_tx header: "A start pulse while a frame is in flight is ignored.").
module uart_tx_reload_while_busy_repro_tb;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data),
        .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    reg     done   = 1'b0;
    reg [8*64-1:0] nonce;

    reg [7:0] rx_byte;
    reg       rx_stop;
    reg       rx_start_ok;

    task check(input cond, input [8*48-1:0] what);
        begin
            if (cond) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("CHECK FAILED: %0s at %0t", what, $time);
            end
        end
    endtask

    // Receive one 8N1 frame, sampling at the middle of each bit (negedge).
    task recv;
        integer i;
        begin
            @(negedge clk);
            while (tx !== 1'b0) @(negedge clk);
            repeat (CPB / 2) @(negedge clk);
            rx_start_ok = (tx === 1'b0);
            for (i = 0; i < 8; i = i + 1) begin
                repeat (CPB) @(negedge clk);
                rx_byte[i] = tx;
            end
            repeat (CPB) @(negedge clk);
            rx_stop = tx;
        end
    endtask

    task pulse_start(input [7:0] value);
        begin
            @(negedge clk);
            start = 1'b1;
            data  = value;
            @(negedge clk);
            start = 1'b0;
            data  = 8'd0;
        end
    endtask

    task finish_with_verdict;
        begin
            if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                nonce = "none";
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    endtask

    initial begin
        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);

        // Frame 1: no interference, 0x3C.
        fork
            recv;
            pulse_start(8'h3C);
        join
        check(rx_byte === 8'h3C && rx_start_ok, "frame1 data 0x3C");
        check(rx_stop === 1'b1, "frame1 stop bit high");

        while (busy) @(negedge clk);
        repeat (2) @(negedge clk);

        // Frame 2: 0xA5, with a start pulse carrying 0x5A mid-frame.
        fork
            recv;
            begin
                pulse_start(8'hA5);
                repeat (CPB * 2) @(negedge clk);
                if (busy) begin
                    start = 1'b1;
                    data  = 8'h5A;
                    @(negedge clk);
                    start = 1'b0;
                    data  = 8'd0;
                end
            end
        join
        check(rx_byte === 8'hA5 && rx_start_ok, "frame2 data unaffected 0xA5");
        check(rx_stop === 1'b1, "frame2 stop bit high");

        repeat (CPB * 3) @(negedge clk);
        check(busy === 1'b0 && tx === 1'b1, "idle after frame2");

        done = 1'b1;
        finish_with_verdict;
    end

    // Watchdog: a hang counts as a failed check.
    initial begin
        #200000;
        if (!done) begin
            failed = failed + 1;
            $display("CHECK FAILED: watchdog timeout");
            finish_with_verdict;
        end
    end
endmodule
=== END FILE ===

